WITH exploded AS (SELECT id, effective_from, currency, element FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) li AS element) SELECT *, CUME_DIST() OVER (PARTITION BY currency ORDER BY element DESC NULLS LAST) AS element_cume_dist, MAX(element) OVER (PARTITION BY currency) AS currency_max_element, CUME_DIST() OVER (PARTITION BY currency ORDER BY element DESC) AS element_cume_dist_2, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY element NULLS LAST) AS element_percent_rank, DENSE_RANK() OVER (ORDER BY element) AS element_dense_rank FROM exploded WHERE currency IN ('EUR', 'USD')
